//! Generate the JavaScript glue module from import descriptors.

use crate::descriptor::{AbiArg, Descriptor, Kind, Ret};
use crate::exports::{Export, ExportArg, ExportRet, Payload};
use crate::wasm::MemoryImport;
use std::fmt::Write;

mod payload;
use payload::{read_payload, sret_call, write_payload};

const PREAMBLE: &str = "\
// Generated by wasm_lite_codegen — do not edit.
let __wl_memory;
let __wl_instance;
// The compiled module, kept so spawned threads (Web Workers) can reuse it.
let __wl_module;
// True when linear memory is a SharedArrayBuffer (an `+atomics` shared-memory
// build). TextDecoder rejects shared-backed views, so we copy before decoding.
let __wl_shared = false;

// Decode `len` UTF-8 bytes at `ptr` from the module's linear memory. A fresh
// view is taken each call so it stays valid if the module grows its memory.
function __wl_str(ptr, len) {
    const __view = new Uint8Array(__wl_memory.buffer, ptr, len);
    return new TextDecoder(\"utf-8\").decode(__wl_shared ? __view.slice() : __view);
}

// Copy a JS string into wasm memory for an export argument; returns [ptr, len].
// The caller frees it with __wl_free after the call.
function __wl_pass_str(s) {
    const bytes = new TextEncoder().encode(s);
    const ptr = __wl_instance.exports.__wl_malloc(bytes.length);
    new Uint8Array(__wl_memory.buffer, ptr, bytes.length).set(bytes);
    return [ptr, bytes.length];
}

// Copy bytes into wasm memory for an export argument; returns [ptr, len]. Accepts
// a Uint8Array (or anything Uint8Array's constructor coerces, e.g. a number[]).
function __wl_pass_bytes(a) {
    const bytes = a instanceof Uint8Array ? a : new Uint8Array(a);
    const ptr = __wl_instance.exports.__wl_malloc(bytes.length);
    new Uint8Array(__wl_memory.buffer, ptr, bytes.length).set(bytes);
    return [ptr, bytes.length];
}

// Value table: opaque handles to JS values. Rust holds an index; the table
// holds the real object. Freed slots are reused.
//
// The first four slots are permanently the JS singletons, so Rust can name
// them as constants and passing one costs no table churn. __wl_drop ignores
// them; they are never on the free list.
const __wl_heap = [undefined, null, true, false];
const __wl_free = [];
function __wl_add(value) {
    const idx = __wl_free.length > 0 ? __wl_free.pop() : __wl_heap.length;
    __wl_heap[idx] = value;
    return idx;
}
function __wl_obj(idx) {
    return __wl_heap[idx];
}
function __wl_drop(idx) {
    if (idx < 4) return;   // a reserved singleton
    __wl_heap[idx] = undefined;
    __wl_free.push(idx);
}
// A second, independently-owned handle to the same JS value. The table holds
// references, so this is a slot allocation, not a copy of the object.
function __wl_clone(idx) {
    return __wl_add(__wl_heap[idx]);
}
// Handles to primitive JS values. `kind` picks null/undefined/true/false so one
// import covers the four singletons.
function __wl_num(v) { return __wl_add(v); }
// A wasm i64 param is already a BigInt on this side.
function __wl_bigint(v) { return __wl_add(v); }
function __wl_ubigint(v) { return __wl_add(BigInt.asUintN(64, v)); }
// Wider than 64 bits: the value arrives as decimal text, since no wasm
// parameter can carry it.
function __wl_bigint_str(ptr, len) { return __wl_add(BigInt(__wl_str(ptr, len))); }

function __wl_str_val(ptr, len) { return __wl_add(__wl_str(ptr, len)); }
// A handle to the module's linear memory object, which threading polyfills
// need to hand to a worker.
function __wl_memory_obj() { return __wl_add(__wl_memory); }
// The compiled module, which a thread spawner passes to a worker.
function __wl_module_obj() { return __wl_add(__wl_module); }
// JS strict equality between two handles.
function __wl_eq(a, b) { return __wl_heap[a] === __wl_heap[b] ? 1 : 0; }
// JS operators on the values two handles denote. One import with an opcode
// rather than a dozen imports, since they differ only in the operator.
function __wl_binop(op, a, b) {
    const x = __wl_heap[a], y = __wl_heap[b];
    switch (op) {
        case 0: return __wl_add(x + y);
        case 1: return __wl_add(x - y);
        case 2: return __wl_add(x * y);
        case 3: return __wl_add(x / y);
        case 4: return __wl_add(x % y);
        case 5: return __wl_add(x & y);
        case 6: return __wl_add(x | y);
        case 7: return __wl_add(x ^ y);
        case 8: return __wl_add(x << y);
        case 9: return __wl_add(x >> y);
        case 10: return __wl_add(x >>> y);
        default: return __wl_add(x ** y);
    }
}
// Three-way comparison. 2 means unordered, which is what JS gives for NaN and
// for values whose coercion does not compare.
function __wl_cmp(a, b) {
    const x = __wl_heap[a], y = __wl_heap[b];
    if (x < y) return -1;
    if (x > y) return 1;
    if (x == y) return 0;
    return 2;
}
// JS type predicates, by opcode.
function __wl_is(kind, a) {
    const x = __wl_heap[a];
    switch (kind) {
        case 0: return typeof x === \"object\" && x !== null ? 1 : 0;
        case 1: return typeof x === \"function\" ? 1 : 0;
        case 2: return typeof x === \"string\" ? 1 : 0;
        case 3: return x === null ? 1 : 0;
        case 4: return x === undefined ? 1 : 0;
        case 5: return x ? 1 : 0;
        case 6: return typeof x === \"bigint\" ? 1 : 0;
        default: return typeof x === \"symbol\" ? 1 : 0;
    }
}
// `/` that hands back whatever it throws instead of propagating — BigInt
// division by zero raises RangeError, and js-sys reports that as a value.
// The decimal text of a numeric handle. Text rather than a wasm parameter
// because the same path has to serve i64 through u128, and no parameter is
// wide enough for the latter.
function __wl_num_str(idx, out) {
    const v = __wl_heap[idx];
    if (typeof v !== \"bigint\" && typeof v !== \"number\") return 0;
    const b = new TextEncoder().encode(String(v));
    const p = __wl_instance.exports.__wl_malloc(b.length);
    new Uint8Array(__wl_memory.buffer, p, b.length).set(b);
    const dv = new DataView(__wl_memory.buffer);
    dv.setUint32(out, p, true);
    dv.setUint32(out + 4, b.length, true);
    return 1;
}
function __wl_checked_div(a, b) {
    try { return __wl_add(__wl_heap[a] / __wl_heap[b]); }
    catch (e) { return __wl_add(e); }
}
function __wl_unop(op, a) {
    const x = __wl_heap[a];
    switch (op) {
        case 0: return __wl_add(-x);
        case 1: return __wl_add(!x);
        default: return __wl_add(~x);
    }
}
// Reading a primitive back out of a handle. Each returns 1/0 for present/absent
// and writes the value through `out`, so a genuine NaN or empty string is not
// confused with the wrong type. A fresh DataView per call: a malloc in between
// can grow memory and detach an older one.
function __wl_as_f64(idx, out) {
    const v = __wl_heap[idx];
    if (typeof v !== \"number\") return 0;
    new DataView(__wl_memory.buffer).setFloat64(out, v, true);
    return 1;
}
function __wl_as_bool(idx, out) {
    const v = __wl_heap[idx];
    if (typeof v !== \"boolean\") return 0;
    new DataView(__wl_memory.buffer).setInt32(out, v ? 1 : 0, true);
    return 1;
}
function __wl_as_str(idx, out) {
    const v = __wl_heap[idx];
    if (typeof v !== \"string\") return 0;
    const b = new TextEncoder().encode(v);
    const p = __wl_instance.exports.__wl_malloc(b.length);
    new Uint8Array(__wl_memory.buffer, p, b.length).set(b);
    const dv = new DataView(__wl_memory.buffer);
    dv.setUint32(out, p, true);
    dv.setUint32(out + 4, b.length, true);
    return 1;
}

// Async executor support. Drive one executor turn; a panic in a polled task
// traps here, which we turn into a test failure (fail-closed) rather than an
// uncaught error in a timer/microtask callback.
function __wl_tick() {
    try {
        __wl_instance.exports.__wl_async_tick();
    } catch (e) {
        globalThis.__wl_done = { ok: false, error: String((e && e.stack) || e) };
    }
}
// __wl_schedule kicks one event-loop turn; only called when the module uses
// `spawn_local`.
function __wl_schedule() {
    setTimeout(__wl_tick, 0);
}

// Sleep the executor until a Waker bumps the wake atom. `Atomics.waitAsync`
// resolves on a `memory.atomic.notify` to `ptr` — including one from another
// worker — so cross-thread wakes reach the main thread without busy-polling.
function __wl_wait_async(ptr, expected) {
    if (typeof Atomics.waitAsync === \"function\") {
        const r = Atomics.waitAsync(new Int32Array(__wl_memory.buffer), ptr >>> 2, expected);
        if (r.async) { r.value.then(__wl_tick); return; }
    }
    // No waitAsync, or the value already changed (\"not-equal\"): re-poll soon.
    setTimeout(__wl_tick, 0);
}

// Cancellable Rust timers. A normal wasm module owns its timers in this realm.
// A shared-memory worker proxies them to the root realm, whose event loop
// outlives the worker that created the future. The root consumes each token
// exactly once by calling either __wl_timer_fire or __wl_timer_cancelled.
const __wl_timers = new Map();
let __wl_timer_handle = null;
function __wl_timer_schedule() {
    if (__wl_timer_handle !== null) clearTimeout(__wl_timer_handle);
    __wl_timer_handle = null;
    if (__wl_timers.size === 0) return;
    let next = Infinity;
    for (const deadline of __wl_timers.values()) next = Math.min(next, deadline);
    __wl_timer_handle = setTimeout(__wl_timer_drain, Math.max(0, next - performance.now()));
}
function __wl_timer_drain() {
    __wl_timer_handle = null;
    const now = performance.now();
    const ready = [];
    for (const [token, deadline] of __wl_timers) {
        if (deadline <= now) {
            __wl_timers.delete(token);
            ready.push(token);
        }
    }
    __wl_timer_schedule();
    for (const token of ready) __wl_instance.exports.__wl_timer_fire(token);
}
function __wl_timer_arm_local(token, delay) {
    __wl_timers.set(token, performance.now() + Math.max(0, delay));
    __wl_timer_schedule();
}
function __wl_timer_cancel_local(token) {
    if (!__wl_timers.delete(token)) return;
    __wl_timer_schedule();
    __wl_instance.exports.__wl_timer_cancelled(token);
}
function __wl_timer_arm(token, delay) {
    if (__wl_shared && globalThis.__wl_spawned_worker === true) {
        self.postMessage({ __wl_timer_arm: [token, delay] });
    } else {
        __wl_timer_arm_local(token, delay);
    }
}
function __wl_timer_cancel(token) {
    if (__wl_shared && globalThis.__wl_spawned_worker === true) {
        self.postMessage({ __wl_timer_cancel: token });
    } else {
        __wl_timer_cancel_local(token);
    }
}

function __wl_spawn_unavailable(_work) {
    throw new Error(\"wasm_lite: thread::spawn requires a shared-memory +atomics build\");
}

// Fail-closed async-test verdict. The test body marks itself \"pending\" so the
// bootstrap won't declare success when `main` returns; the body signals pass
// when it actually completes. A panic in between fails via __wl_tick above, and
// a hang falls to the runner's timeout — so an async test can never pass by
// default.
function __wl_test_pending() { globalThis.__wl_async_pending = true; }
function __wl_test_pass() { globalThis.__wl_done = { ok: true, error: \"\" }; }

// Cross-realm log bridge. A worker is a separate JS realm, so its console output
// is invisible to the (headless) test runner, which only captures the main realm.
// Workers forward each console line up the spawn chain via postMessage; at the
// main realm it is replayed into the page's console (where the runner captures
// it). Keeps detached-worker panics from being silent on the CLI.
const __wl_is_worker = typeof WorkerGlobalScope !== \"undefined\" && self instanceof WorkerGlobalScope;
function __wl_sink_log(level, text) {
    if (__wl_is_worker) {
        self.postMessage({ __wl_log: [level, text] });   // relay up to our parent
    } else {
        (globalThis.console[level] || globalThis.console.log)(text);   // main: page captures it
    }
}

// A JS exception escaping a non-Result import unwinds the wasm frames without
// running Rust destructors or restoring the shadow stack pointer — the
// instance's state is as suspect as after a panic. Record the failure
// (fail-closed for tests), log it loudly, and rethrow; every further export
// call is refused via __wl_check_live. (Result-returning imports catch the
// exception and hand it to Rust instead — bind throwy JS as `Result<_, JsValue>`.)
let __wl_dead = null;
function __wl_fatal(e, name) {
    __wl_dead = \"imported JS function \" + name + \" threw: \" + String((e && e.stack) || e);
    __wl_sink_log(\"error\", \"wasm_lite: \" + __wl_dead + \" — the wasm instance is now unusable; bind the import as Result<_, JsValue> to handle JS exceptions instead\");
    if (!globalThis.__wl_done) globalThis.__wl_done = { ok: false, error: __wl_dead };
    throw e;
}
function __wl_check_live() {
    if (__wl_dead) throw new Error(\"wasm_lite: instance is unusable: \" + __wl_dead);
}

// Wrap a Rust closure as a JS function. `id` indexes a *Rust-side* registry,
// not a pointer: dropping the Closure removes the entry, so a JS reference that
// outlives it (an unregistered listener, say) calls a no-op instead of reading
// freed memory. Arity picks the trampoline; a one-argument closure takes
// ownership of its argument's table slot, matching the export convention.
function __wl_closure_new(id, arity) {
    let f;
    if (arity === 0) {
        f = () => { __wl_check_live(); __wl_instance.exports.__wl_closure_call_0(id); };
    } else if (arity === 1) {
        f = (a) => { __wl_check_live(); __wl_instance.exports.__wl_closure_call_1(id, __wl_add(a)); };
    } else {
        // Variadic: pack one table index per argument into a buffer wasm can
        // read. The Uint32Array view is taken *after* the malloc, which may
        // grow memory and detach any earlier view.
        f = function (...args) {
            __wl_check_live();
            const n = args.length;
            const ptr = __wl_instance.exports.__wl_malloc(n * 4);
            const view = new Uint32Array(__wl_memory.buffer, ptr, n);
            for (let i = 0; i < n; i++) view[i] = __wl_add(args[i]);
            const r = __wl_instance.exports.__wl_closure_call_n(id, n, ptr) >>> 0;
            __wl_instance.exports.__wl_free(ptr, n * 4);
            // 0 is: returned nothing. Otherwise the low bits are the handle
            // plus one, and the high bit means throw it rather than return it.
            if (r === 0) return undefined;
            const h = (r & 0x7fffffff) - 1;
            const out = __wl_obj(h);
            __wl_drop(h);
            if (r & 0x80000000) throw out;
            return out;
        };
    }
    return __wl_add(f);
}

";

/// The `instantiate`/`setInstance` exports for a module with its own (exported)
/// memory — the default case.
const INSTANTIATE: &str = "
export async function instantiate(wasmUrl) {
    const { module, instance } = await WebAssembly.instantiateStreaming(fetch(wasmUrl), makeImports());
    __wl_module = module;
    __wl_instance = instance;
    __wl_memory = instance.exports.memory;
    return instance;
}

// Used by the interop loader, which instantiates the merged module itself and
// then hands us the instance.
export function setInstance(instance) {
    __wl_instance = instance;
    __wl_memory = instance.exports.memory;
}
";

/// The `instantiate`/`setInstance` exports for a module that *imports* a shared
/// memory (an `+atomics` `--import-memory` build). JS creates the
/// `WebAssembly.Memory` (or a worker passes in the one it received) and supplies
/// it as an import. `makeMemory()` is exported so a future thread spawner can
/// create the shared memory once and hand the same object to every worker.
fn instantiate_shared(mem: &MemoryImport, worker_specifier: &str) -> String {
    let module = js_string(&mem.module);
    let name = js_string(&mem.name);
    let worker_specifier = js_string(worker_specifier);
    let maximum = mem
        .maximum
        .map_or(String::new(), |m| format!(", maximum: {m}"));
    let shared = mem.shared;
    format!(
        "
export function makeMemory() {{
    return new WebAssembly.Memory({{ initial: {initial}{maximum}, shared: {shared} }});
}}

export async function instantiate(wasmUrl, memory) {{
    __wl_memory = memory || makeMemory();
    __wl_shared = {shared};
    const imports = makeImports();
    imports[{module}] = imports[{module}] || Object.create(null);
    imports[{module}][{name}] = __wl_memory;
    const {{ module: m, instance }} = await WebAssembly.instantiateStreaming(fetch(wasmUrl), imports);
    __wl_module = m;
    __wl_instance = instance;
    return instance;
}}

// Used by the interop loader / a worker that already has the shared memory and
// the compiled module.
export function setInstance(instance, memory, module) {{
    __wl_instance = instance;
    __wl_memory = memory;
    __wl_module = module;
    __wl_shared = {shared};
}}

// Per-thread stack size for spawned workers.
const __WL_STACK = 1 << 20;
// Keep live workers referenced so they are not garbage-collected mid-run.
const __wl_workers = new Set();

// Runtime import: spawn a Web Worker for the boxed closure `work`. Allocates a
// fresh stack + TLS block, then hands the worker this module + shared memory.
//
// The allocation happens on the calling thread (the memory is shared, so any
// thread's allocator serves), but the *worker creation* is delegated to the
// main thread whenever we are ourselves a worker. Chrome will not start a
// nested worker while its parent worker is blocked: the child's module script
// is fetched through the parent, and a parent sitting in `Atomics.wait` — which
// is what `join`, `park` and every blocking lock do — never services it. The
// child then never runs and the parent waits forever. (Firefox does not have
// this problem, which is why a Firefox-only CI never saw it.) Sending the
// request to the main thread, whose event loop is always turning, sidesteps it
// entirely and costs one postMessage.
function __wl_spawn(work) {{
    const stackPtr = __wl_instance.exports.__wl_thread_alloc(__WL_STACK);
    const tlsSize = __wl_instance.exports.__tls_size.value;
    const tlsPtr = tlsSize ? __wl_instance.exports.__wl_thread_alloc(tlsSize) : 0;
    __wl_spawn_at(work, stackPtr, tlsPtr, tlsSize);
}}

// Create the worker, or ask our creator to. Called with a stack and TLS block
// already allocated, so it is position-independent: whoever ends up running it
// hands the same pointers to the new thread.
//
// Because every worker takes this path, the main thread creates all of them —
// so a worker's creator is always the main thread and this is always one hop,
// never a chain. Rust-side nesting depth is unbounded; the messaging is flat.
function __wl_spawn_at(work, stackPtr, tlsPtr, tlsSize) {{
    if (__wl_is_worker) {{
        self.postMessage({{ __wl_spawn_req: [work, stackPtr, tlsPtr, tlsSize] }});
        return;
    }}
    globalThis.__wl_spawn_count = (globalThis.__wl_spawn_count || 0) + 1;
    const w = new Worker(new URL({worker_specifier}, import.meta.url), {{ type: \"module\" }});
    __wl_workers.add(w);
    // A worker that fails to start — a fetch the page's COEP rejects, a syntax
    // error in the bootstrap, a nested-worker restriction — reports through
    // `onerror` and nowhere else. Without this it is perfectly silent: the
    // spawn appears to succeed and the thread simply never runs.
    w.onerror = (e) => {{
        __wl_sink_log(\"error\", \"wasm_lite: spawned worker failed to start: \" +
            ((e && (e.message || e.filename)) ? ((e.message || \"\") + \" @ \" + (e.filename || \"?\") + \":\" + (e.lineno || 0)) : String(e)));
    }};
    w.onmessageerror = (e) => {{
        __wl_sink_log(\"error\", \"wasm_lite: spawned worker could not deserialize its start message \" +
            \"(a WebAssembly.Module or SharedArrayBuffer needs a cross-origin-isolated page): \" + String(e));
    }};
    w.onmessage = (e) => {{
        const m = e.data;
        if (m && m.__wl_log) {{ __wl_sink_log(m.__wl_log[0], m.__wl_log[1]); }}   // forward worker console up
        // A thread this worker spawned: create it here (or relay further up).
        // Its stack and TLS are already allocated in the shared memory.
        else if (m && m.__wl_spawn_req) {{ __wl_spawn_at(...m.__wl_spawn_req); }}
        else if (m && m.__wl_timer_arm) {{ __wl_timer_arm_local(...m.__wl_timer_arm); }}
        else if (m && m.__wl_timer_cancel !== undefined) {{ __wl_timer_cancel_local(m.__wl_timer_cancel); }}
        else {{                                                                   // \"done\"
            globalThis.__wl_worker_done = (globalThis.__wl_worker_done || 0) + 1;
            __wl_workers.delete(w);
            w.terminate();
        }}
    }};
    w.postMessage({{
        module: __wl_module, memory: __wl_memory, work,
        stackPtr, stackTop: stackPtr + __WL_STACK, stackSize: __WL_STACK, tlsPtr, tlsSize,
    }});
}}
",
        initial = mem.initial,
    )
}

/// Generate the worker bootstrap module for spawned threads.
///
/// `glue_specifier` is the module specifier the worker imports the glue from
/// (a sibling of the worker file, e.g. `"./program.js"`). The worker receives a
/// message with the compiled module, the shared memory, the boxed `work`
/// pointer, and a freshly allocated stack + TLS block; it instantiates the same
/// module on the same memory, points this thread's `__stack_pointer` at the new
/// stack, initializes TLS, runs the entry trampoline, then frees and closes.
pub fn generate_worker(glue_specifier: &str) -> String {
    let glue = js_string(glue_specifier);
    format!(
        "// Generated by wasm_lite_codegen — worker bootstrap for spawned threads.
import {{ makeImports, setInstance }} from {glue};

// Runtime imports use this marker to proxy realm-bound services (notably
// timers) to the root shared-memory instance.
globalThis.__wl_spawned_worker = true;

// Forward this worker's console output to our parent so it reaches the main
// realm (and the test runner / CLI). Still log locally for browser devtools.
for (const __l of [\"log\", \"error\", \"warn\", \"info\"]) {{
    const __orig = console[__l] ? console[__l].bind(console) : function () {{}};
    console[__l] = (...a) => {{ __orig(...a); self.postMessage({{ __wl_log: [__l, a.join(\" \")] }}); }};
}}

// This handler is `async`, so anything it throws becomes an *unhandled
// rejection* — which does not reach the parent's `onerror` and is therefore
// invisible from the outside. These listeners are the only way a failure
// between \"worker started\" and \"closure running\" gets reported at all.
self.addEventListener(\"error\", (ev) => {{
    self.postMessage({{ __wl_log: [\"error\", \"wasm_lite: worker error: \" + (ev.message || ev)] }});
}});
self.addEventListener(\"unhandledrejection\", (ev) => {{
    const r = ev.reason;
    self.postMessage({{ __wl_log: [\"error\", \"wasm_lite: worker failed to start: \" + ((r && (r.stack || r.message)) || r)] }});
}});

self.onmessage = async (e) => {{
    const {{ module, memory, work, stackPtr, stackTop, stackSize, tlsPtr, tlsSize }} = e.data;
    const imports = makeImports();
    imports[\"env\"] = imports[\"env\"] || {{}};
    imports[\"env\"][\"memory\"] = memory;
    const instance = await WebAssembly.instantiate(module, imports);
    setInstance(instance, memory, module);
    // Give this thread its own stack and TLS, then run the closure.
    instance.exports.__stack_pointer.value = stackTop;
    if (tlsSize) instance.exports.__wasm_init_tls(tlsPtr);

    const finish = () => {{
        instance.exports.__wl_thread_free(stackPtr, stackSize);
        if (tlsSize) instance.exports.__wl_thread_free(tlsPtr, tlsSize);
        self.postMessage(\"done\");
        self.close();
    }};

    // A panic traps the instance; its state is suspect, so tear down at once
    // (the panic was already logged + routed to any joiner).
    let panicked = false;
    try {{
        instance.exports.__wl_thread_entry(work);
    }} catch (_e) {{
        panicked = true;
    }}

    // Drain the event-loop executor before teardown: if the closure called
    // `spawn_local`, its tasks live in this thread's TLS and are still pending —
    // freeing now would drop them and free the TLS underneath them. Wait until
    // the executor is idle (it self-drives via the scheduler), then tear down.
    const idle = instance.exports.__wl_executor_idle;
    if (panicked || !idle || idle()) {{
        finish();
    }} else {{
        (function drain() {{ idle() ? finish() : setTimeout(drain, 0); }})();
    }}
}};
"
    )
}

/// Generate the JS glue module for the given imports and exports.
///
/// The module exports `makeImports()` (the import object the wasm expects),
/// `instantiate(wasmUrl)` (fetch + instantiate), and one wrapper per
/// `#[wasm_lite::export]` function.
///
/// `memory` describes an imported (shared) linear memory when the module was
/// linked with `--import-memory` (an `+atomics` build); pass `None` for the
/// usual module-defined memory.
pub fn generate_glue(
    imports: &[Descriptor],
    exports: &[Export],
    memory: Option<&MemoryImport>,
) -> String {
    generate_glue_with_worker(imports, exports, memory, "./wl_worker.js")
}

/// Generate glue whose shared-memory thread spawner loads `worker_specifier`.
///
/// This is the same output as [`generate_glue`], except callers that emit files
/// to disk can give every bundle a distinct worker module rather than sharing
/// the default `./wl_worker.js` name.
pub fn generate_glue_with_worker(
    imports: &[Descriptor],
    exports: &[Export],
    memory: Option<&MemoryImport>,
    worker_specifier: &str,
) -> String {
    let mut js = String::from(PREAMBLE);
    // Null-prototype objects make wasm import names literal keys. On ordinary
    // objects, names such as `__proto__` and `constructor` mutate or resolve
    // through Object.prototype instead of defining the requested import.
    js.push_str("export function makeImports() {\n    const imports = Object.create(null);\n");
    // Runtime support: Rust calls __wl_drop when a JsValue drops, __wl_schedule
    // to drive the async executor; shared-memory builds also get __wl_spawn for
    // thread spawning. (Unused entries are harmless — the wasm only imports what
    // it references.)
    let test_rt = "__wl_test_pending: __wl_test_pending, __wl_test_pass: __wl_test_pass, __wl_closure_new: __wl_closure_new, __wl_clone: __wl_clone, __wl_num: __wl_num, __wl_bigint: __wl_bigint, __wl_ubigint: __wl_ubigint, __wl_bigint_str: __wl_bigint_str, __wl_str_val: __wl_str_val, __wl_as_f64: __wl_as_f64, __wl_as_bool: __wl_as_bool, __wl_as_str: __wl_as_str, __wl_eq: __wl_eq, __wl_binop: __wl_binop, __wl_unop: __wl_unop, __wl_cmp: __wl_cmp, __wl_is: __wl_is, __wl_checked_div: __wl_checked_div, __wl_num_str: __wl_num_str, __wl_memory_obj: __wl_memory_obj, __wl_module_obj: __wl_module_obj";
    if memory.is_some_and(|memory| memory.shared) {
        let _ = writeln!(
            js,
            "    imports[\"__wasm_lite\"] = Object.assign(Object.create(null), {{ __wl_drop: __wl_drop, __wl_spawn: __wl_spawn, __wl_schedule: __wl_schedule, __wl_wait_async: __wl_wait_async, __wl_timer_arm: __wl_timer_arm, __wl_timer_cancel: __wl_timer_cancel, {test_rt} }});"
        );
    } else {
        let _ = writeln!(
            js,
            "    imports[\"__wasm_lite\"] = Object.assign(Object.create(null), {{ __wl_drop: __wl_drop, __wl_spawn: __wl_spawn_unavailable, __wl_schedule: __wl_schedule, __wl_wait_async: __wl_wait_async, __wl_timer_arm: __wl_timer_arm, __wl_timer_cancel: __wl_timer_cancel, {test_rt} }});"
        );
    }

    for d in imports {
        emit_shim(&mut js, d);
    }

    // Fail closed: wrap every import shim so an escaping JS exception is routed
    // through __wl_fatal instead of silently unwinding the wasm frames.
    // Result-returning shims already catch and never reach the wrapper's catch;
    // runtime entries (__wl_spawn in particular — a throwing `new Worker()`
    // would otherwise leak the closure and its stack/TLS blocks) are covered too.
    js.push_str(
        "    for (const __ns in imports) {\n\
         \x20       for (const __key in imports[__ns]) {\n\
         \x20           const __f = imports[__ns][__key];\n\
         \x20           if (typeof __f !== \"function\") continue;\n\
         \x20           imports[__ns][__key] = (...__a) => {\n\
         \x20               try { return __f(...__a); } catch (__e) { __wl_fatal(__e, __ns + \".\" + __key); }\n\
         \x20           };\n\
         \x20       }\n\
         \x20   }\n",
    );
    js.push_str("    return imports;\n}\n");
    match memory {
        Some(mem) => js.push_str(&instantiate_shared(mem, worker_specifier)),
        None => js.push_str(INSTANTIATE),
    }

    for (index, export) in exports.iter().enumerate() {
        emit_export(&mut js, export, index);
    }
    js
}

/// Emit one export wrapper: a JS function that marshals `&str` args into wasm
/// memory, forwards to the export shim, frees, and unwraps the return.
fn emit_export(js: &mut String, export: &Export, index: usize) {
    let params: Vec<String> = (0..export.args.len()).map(|i| format!("p{i}")).collect();

    let mut lines = Vec::new();
    // Refuse re-entry after an escaped import exception: the shadow stack
    // pointer was not restored, so running more wasm would be silent UB.
    lines.push("__wl_check_live();".to_string());
    let mut wasm_args = Vec::new();
    let mut frees = Vec::new();
    for (i, arg) in export.args.iter().enumerate() {
        match arg {
            ExportArg::Num => wasm_args.push(format!("p{i}")),
            ExportArg::Str => {
                lines.push(format!("const [__a{i}p, __a{i}l] = __wl_pass_str(p{i});"));
                wasm_args.push(format!("__a{i}p"));
                wasm_args.push(format!("__a{i}l"));
                frees.push(format!(
                    "__wl_instance.exports.__wl_free(__a{i}p, __a{i}l);"
                ));
            }
            ExportArg::Bytes => {
                lines.push(format!("const [__a{i}p, __a{i}l] = __wl_pass_bytes(p{i});"));
                wasm_args.push(format!("__a{i}p"));
                wasm_args.push(format!("__a{i}l"));
                frees.push(format!(
                    "__wl_instance.exports.__wl_free(__a{i}p, __a{i}l);"
                ));
            }
            ExportArg::Handle => {
                // Register the object; Rust owns the handle and frees the slot
                // itself when its JsValue drops, so JS does not free it here.
                lines.push(format!("const __a{i}h = __wl_add(p{i});"));
                wasm_args.push(format!("__a{i}h"));
            }
            ExportArg::Opt(p) => {
                // A nullable arg: discriminant (null/undefined → 0) + payload.
                lines.push(format!(
                    "const __s{i} = (p{i} === null || p{i} === undefined) ? 0 : 1;"
                ));
                wasm_args.push(format!("__s{i}"));
                match p {
                    // `Option<()>` carries nothing beyond its discriminant.
                    Payload::Unit => {}
                    Payload::I32
                    | Payload::U32
                    | Payload::F64
                    | Payload::I8
                    | Payload::I16
                    | Payload::U8
                    | Payload::U16
                    | Payload::F32 => {
                        wasm_args.push(format!("(__s{i} ? p{i} : 0)"));
                    }
                    // A 64-bit wasm param is a BigInt, so its absent value has
                    // to be one too.
                    Payload::I64 | Payload::U64 => {
                        wasm_args.push(format!("(__s{i} ? BigInt(p{i}) : 0n)"));
                    }
                    Payload::Bool => wasm_args.push(format!("(__s{i} ? (p{i} ? 1 : 0) : 0)")),
                    Payload::Handle => {
                        lines.push(format!("const __a{i}h = __s{i} ? __wl_add(p{i}) : 0;"));
                        wasm_args.push(format!("__a{i}h"));
                    }
                    Payload::Str | Payload::Bytes => {
                        let pass = if matches!(p, Payload::Str) {
                            "__wl_pass_str"
                        } else {
                            "__wl_pass_bytes"
                        };
                        // ptr/len default to 0 (a null pointer + zero length → None
                        // on the Rust side); __wl_free(0, 0) is a no-op.
                        lines.push(format!("let __a{i}p = 0, __a{i}l = 0; if (__s{i}) {{ [__a{i}p, __a{i}l] = {pass}(p{i}); }}"));
                        wasm_args.push(format!("__a{i}p"));
                        wasm_args.push(format!("__a{i}l"));
                        frees.push(format!(
                            "__wl_instance.exports.__wl_free(__a{i}p, __a{i}l);"
                        ));
                    }
                }
            }
        }
    }

    let wasm_name = js_string(&format!("__wl_export_{}", export.name));
    let call = format!(
        "__wl_instance.exports[{wasm_name}]({})",
        wasm_args.join(", ")
    );

    match export.ret {
        ExportRet::Void => {
            lines.push(format!("{call};"));
            lines.extend(frees);
        }
        ExportRet::Value => {
            lines.push(format!("const __ret = {call};"));
            lines.extend(frees);
            lines.push("return __ret;".into());
        }
        ExportRet::U32 => {
            // The wasm i32 result surfaces as a signed Number; reinterpret.
            lines.push(format!("const __ret = {call};"));
            lines.extend(frees);
            lines.push("return __ret >>> 0;".into());
        }
        ExportRet::Bool => {
            lines.push(format!("const __ret = {call};"));
            lines.extend(frees);
            lines.push("return Boolean(__ret);".into());
        }
        ExportRet::Str => {
            lines.push(format!("const __ret = {call};"));
            lines.extend(frees);
            // The shim returns a packed i64 (BigInt in JS): (ptr << 32) | len.
            lines.push("const __packed = BigInt.asUintN(64, __ret);".into());
            lines.push(
                "const __p = Number(__packed >> 32n), __l = Number(__packed & 0xffffffffn);".into(),
            );
            lines.push("const __s = __wl_str(__p, __l);".into());
            lines.push("__wl_instance.exports.__wl_free(__p, __l);".into());
            lines.push("return __s;".into());
        }
        ExportRet::Bytes => {
            lines.push(format!("const __ret = {call};"));
            lines.extend(frees);
            lines.push("const __packed = BigInt.asUintN(64, __ret);".into());
            lines.push(
                "const __p = Number(__packed >> 32n), __l = Number(__packed & 0xffffffffn);".into(),
            );
            // Copy out of wasm memory before freeing (a view would dangle after free).
            lines.push("const __b = new Uint8Array(__wl_memory.buffer, __p, __l).slice();".into());
            lines.push("__wl_instance.exports.__wl_free(__p, __l);".into());
            lines.push("return __b;".into());
        }
        ExportRet::Handle => {
            lines.push(format!("const __idx = {call};"));
            lines.extend(frees);
            // Rust transferred ownership (it `forget`s the JsValue); read the
            // object out, free the now-orphaned table slot, and hand it to JS.
            lines.push("const __o = __wl_obj(__idx);".into());
            lines.push("__wl_drop(__idx);".into());
            lines.push("return __o;".into());
        }
        // sret returns: Rust wrote a discriminant at __ret and a payload at
        // __ret+8. The buffer is the export's leading argument.
        ExportRet::Opt(p) => {
            let sret_call = sret_call(&wasm_name, &wasm_args);
            lines.push("const __ret = __wl_instance.exports.__wl_malloc(16);".into());
            lines.push(format!("{sret_call};"));
            lines.extend(frees);
            lines.push("const __dv = new DataView(__wl_memory.buffer);".into());
            lines.push("let __result;".into());
            lines.push("if (__dv.getUint32(__ret, true) === 1) {".into());
            let (stmts, expr) = read_payload(p, "__ret + 8", "v");
            for s in stmts {
                lines.push(format!("    {s}"));
            }
            lines.push(format!("    __result = {expr};"));
            lines.push("} else { __result = null; }".into());
            lines.push("__wl_instance.exports.__wl_free(__ret, 16);".into());
            lines.push("return __result;".into());
        }
        ExportRet::Res(ok, err) => {
            let sret_call = sret_call(&wasm_name, &wasm_args);
            lines.push("const __ret = __wl_instance.exports.__wl_malloc(16);".into());
            lines.push(format!("{sret_call};"));
            lines.extend(frees);
            lines.push("const __dv = new DataView(__wl_memory.buffer);".into());
            lines.push("const __tag = __dv.getUint32(__ret, true);".into());
            lines.push("if (__tag === 0) {".into());
            let (ok_stmts, ok_expr) = read_payload(ok, "__ret + 8", "ok");
            for s in ok_stmts {
                lines.push(format!("    {s}"));
            }
            lines.push(format!("    const __okv = {ok_expr};"));
            lines.push("    __wl_instance.exports.__wl_free(__ret, 16);".into());
            lines.push("    return __okv;".into());
            lines.push("} else {".into());
            let (err_stmts, err_expr) = read_payload(err, "__ret + 8", "err");
            for s in err_stmts {
                lines.push(format!("    {s}"));
            }
            lines.push(format!("    const __errv = {err_expr};"));
            lines.push("    __wl_instance.exports.__wl_free(__ret, 16);".into());
            lines.push("    throw __errv;".into());
            lines.push("}".into());
        }
    }

    // The descriptor comes from the wasm binary. Keep its name data, never JS
    // source: a stable local identifier plus a quoted export alias prevents a
    // crafted custom section from injecting statements into the glue module.
    let wrapper = format!("__wl_export_wrapper_{index}");
    let public_name = js_string(&export.name);
    let _ = writeln!(
        js,
        "\nfunction {wrapper}({}) {{ {} }}\nexport {{ {wrapper} as {public_name} }};",
        params.join(", "),
        lines.join(" ")
    );
}

/// Emit one import shim: a JS function that unmarshals wasm params and calls the
/// real JS function — `globalThis[ns][js_name](args)` for a function, or
/// `receiver[js_name](args)` for a method (whose first argument is the receiver).
fn emit_shim(js: &mut String, d: &Descriptor) {
    let ns = js_string(&d.namespace);
    let import_name = js_string(&d.import_name);

    // Build the wasm-level parameter list and the marshalled JS arguments. For a
    // method, the first (handle) argument is peeled off as the receiver.
    let mut params = Vec::new();
    let mut js_args = Vec::new();
    let mut receiver = None;

    for (i, arg) in d.args.iter().enumerate() {
        let is_receiver = i == 0
            && matches!(
                d.kind,
                Kind::Method
                    | Kind::Getter
                    | Kind::Setter
                    | Kind::IndexGet
                    | Kind::IndexSet
                    | Kind::IndexDelete
                    | Kind::InstanceOf
            );
        let marshalled = match arg {
            AbiArg::Str => {
                let ptr = next_param(&mut params);
                let len = next_param(&mut params);
                format!("__wl_str({ptr}, {len})")
            }
            AbiArg::Bytes => {
                // A transient view into wasm memory — valid for the call's duration.
                let ptr = next_param(&mut params);
                let len = next_param(&mut params);
                format!("new Uint8Array(__wl_memory.buffer, {ptr}, {len})")
            }
            // Like Bytes, a transient view into wasm memory. `len` is in
            // elements, so the typed array's own constructor does the scaling
            // and neither side needs to know the element size.
            AbiArg::Slice(elem) => {
                let ptr = next_param(&mut params);
                let len = next_param(&mut params);
                format!("new {}(__wl_memory.buffer, {ptr}, {len})", elem.js_array())
            }
            // A wasm i64 param arrives as a signed BigInt, which is already the
            // value Rust had.
            AbiArg::I64 => next_param(&mut params),
            // ...and for u64 the same bits need reading unsigned.
            AbiArg::U64 => format!("BigInt.asUintN(64, {})", next_param(&mut params)),
            // A run of table indices in wasm memory, read out as the objects
            // they denote. The view is transient, like the other slices.
            AbiArg::Handles => {
                let ptr = next_param(&mut params);
                let len = next_param(&mut params);
                format!("Array.from(new Uint32Array(__wl_memory.buffer, {ptr}, {len}), __wl_obj)")
            }
            AbiArg::Bool => format!("Boolean({})", next_param(&mut params)),
            AbiArg::Num => next_param(&mut params),
            // The wasm i32 param surfaces as a signed Number; reinterpret.
            AbiArg::U32 => format!("({} >>> 0)", next_param(&mut params)),
            AbiArg::Handle => format!("__wl_obj({})", next_param(&mut params)),
            AbiArg::Opt(p) => {
                // Leading discriminant param, then the inner payload's params.
                let pres = next_param(&mut params);
                let payload = match p {
                    // `Option<()>` occupies no parameter beyond the
                    // discriminant, so there is nothing to unmarshal.
                    Payload::Unit => "undefined".to_string(),
                    Payload::I32
                    | Payload::F64
                    | Payload::I8
                    | Payload::I16
                    | Payload::U8
                    | Payload::U16
                    | Payload::F32
                    | Payload::I64
                    | Payload::U64 => next_param(&mut params),
                    // The wasm i32 param surfaces as a signed Number; reinterpret.
                    Payload::U32 => format!("({} >>> 0)", next_param(&mut params)),
                    Payload::Bool => format!("Boolean({})", next_param(&mut params)),
                    Payload::Handle => format!("__wl_obj({})", next_param(&mut params)),
                    Payload::Str => {
                        let ptr = next_param(&mut params);
                        let len = next_param(&mut params);
                        format!("__wl_str({ptr}, {len})")
                    }
                    Payload::Bytes => {
                        let ptr = next_param(&mut params);
                        let len = next_param(&mut params);
                        format!("new Uint8Array(__wl_memory.buffer, {ptr}, {len})")
                    }
                };
                // `undefined` (not null) for None, so JS default-parameter
                // handling treats the argument as absent.
                format!("({pres} ? {payload} : undefined)")
            }
        };
        if is_receiver {
            receiver = Some(marshalled);
        } else {
            js_args.push(marshalled);
        }
    }

    // `variadic` spreads the last marshalled argument into the call.
    if d.variadic
        && let Some(last) = js_args.last_mut()
    {
        *last = format!("...{last}");
    }

    let params = params.join(", ");

    // `check_shape` has already fixed the arity of every kind that indexes
    // positionally here, so these expects are unreachable for any descriptor
    // that parsed.
    let recv = || receiver.clone().expect("kind has a receiver");
    let arg = |n: usize| {
        js_args
            .get(n)
            .cloned()
            .expect("check_shape fixed this kind's arity")
    };

    // The expression whose *value* is what the import yields. For calls that is
    // a call; for a property write it is an assignment, which in JS evaluates
    // to the assigned value — harmless, since setters are Ret::Void.
    // `js_name` may be a *path* — js-sys binds `Uint8Array.prototype.set.call`
    // — so each dotted segment becomes another lookup.
    let member = |base: &str| {
        let mut out = String::with_capacity(base.len() + d.js_name.len() + 4);
        out.push_str(base);
        for segment in d.js_name.split('.') {
            out.push('[');
            out.push_str(&js_string(segment));
            out.push(']');
        }
        out
    };

    let call = match d.kind {
        Kind::Function => format!(
            "{}({})",
            member(&format!("globalThis[{ns}]")),
            js_args.join(", ")
        ),
        Kind::Method => format!("{}({})", member(&recv()), js_args.join(", ")),
        Kind::Getter => member(&recv()),
        Kind::Setter => format!("{} = {}", member(&recv()), arg(0)),
        Kind::Constructor => format!("new {}({})", member("globalThis"), js_args.join(", ")),
        Kind::StaticGetter => member(&format!("globalThis[{ns}]")),
        Kind::IndexGet => format!("{}[{}]", recv(), arg(0)),
        Kind::IndexDelete => format!("delete {}[{}]", recv(), arg(0)),
        Kind::IndexSet => format!("{}[{}] = {}", recv(), arg(0), arg(1)),
        // Guarded: `instanceof` throws a TypeError if the right-hand side is
        // not a constructor, which is exactly what happens when the class is
        // missing from this engine. A downcast test should answer "no", not
        // kill the instance.
        Kind::InstanceOf => {
            let class = member("globalThis");
            format!(
                "(typeof {class} === \"function\" && {} instanceof {class})",
                recv()
            )
        }
    };

    // Ensure the namespace exists, then assign the shim by wasm import name.
    let _ = writeln!(
        js,
        "    imports[{ns}] = imports[{ns}] || Object.create(null);"
    );
    match &d.ret {
        // A handle return stores the result in the value table and yields its index.
        Ret::Handle => {
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({params}) => __wl_add({call});"
            );
        }
        // A string return is copied into wasm memory; Rust takes ownership and frees.
        Ret::Str => {
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({params}) => {{ \
                     const __r = {call}; \
                     const __b = new TextEncoder().encode(__r); \
                     const __p = __wl_instance.exports.__wl_malloc(__b.length); \
                     new Uint8Array(__wl_memory.buffer, __p, __b.length).set(__b); \
                     return (BigInt(__p) << 32n) | BigInt(__b.length); \
                 }};"
            );
        }
        // A bytes return: coerce to a Uint8Array, copy into wasm memory, hand off.
        Ret::Bytes => {
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({params}) => {{ \
                     const __r = {call}; \
                     const __b = __r instanceof Uint8Array ? __r : new Uint8Array(__r); \
                     const __p = __wl_instance.exports.__wl_malloc(__b.length); \
                     new Uint8Array(__wl_memory.buffer, __p, __b.length).set(__b); \
                     return (BigInt(__p) << 32n) | BigInt(__b.length); \
                 }};"
            );
        }
        // sret returns: the shim writes a discriminant + payload into a leading
        // retptr buffer rather than returning a value.
        Ret::Opt(p) => {
            let shim_params = if params.is_empty() {
                "__retp".to_string()
            } else {
                format!("__retp, {params}")
            };
            let (prep, set) = write_payload(*p, "__retp + 8", "__r");
            let body = format!(
                "const __r = {call}; \
                 if (__r === null || __r === undefined) {{ new DataView(__wl_memory.buffer).setUint32(__retp, 0, true); }} \
                 else {{ {prep} const __dv = new DataView(__wl_memory.buffer); __dv.setUint32(__retp, 1, true); {set} }}",
                prep = prep.join(" "),
                set = set.join(" "),
            );
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({shim_params}) => {{ {body} }};"
            );
        }
        Ret::Res(ok, err) => {
            let shim_params = if params.is_empty() {
                "__retp".to_string()
            } else {
                format!("__retp, {params}")
            };
            let (ok_prep, ok_set) = write_payload(*ok, "__retp + 8", "__r");
            let (err_prep, err_set) = write_payload(*err, "__retp + 8", "__e");
            let body = format!(
                "try {{ const __r = {call}; {ok_prep} const __dv = new DataView(__wl_memory.buffer); \
                 __dv.setUint32(__retp, 0, true); {ok_set} }} \
                 catch (__e) {{ {err_prep} const __dv = new DataView(__wl_memory.buffer); \
                 __dv.setUint32(__retp, 1, true); {err_set} }}",
                ok_prep = ok_prep.join(" "),
                ok_set = ok_set.join(" "),
                err_prep = err_prep.join(" "),
                err_set = err_set.join(" "),
            );
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({shim_params}) => {{ {body} }};"
            );
        }
        // As `Ret::Res`, plus a third outcome: `null`/`undefined` from a
        // successful call means `Ok(None)`.
        Ret::ResOpt(ok, err) => {
            let shim_params = if params.is_empty() {
                "__retp".to_string()
            } else {
                format!("__retp, {params}")
            };
            let (ok_prep, ok_set) = write_payload(*ok, "__retp + 8", "__r");
            let (err_prep, err_set) = write_payload(*err, "__retp + 8", "__e");
            let body = format!(
                "try {{ const __r = {call}; \
                 if (__r === null || __r === undefined) {{ \
                     new DataView(__wl_memory.buffer).setUint32(__retp, 2, true); \
                 }} else {{ \
                     {ok_prep} const __dv = new DataView(__wl_memory.buffer); \
                     __dv.setUint32(__retp, 0, true); {ok_set} \
                 }} }} \
                 catch (__e) {{ {err_prep} const __dv = new DataView(__wl_memory.buffer); \
                 __dv.setUint32(__retp, 1, true); {err_set} }}",
                ok_prep = ok_prep.join(" "),
                ok_set = ok_set.join(" "),
                err_prep = err_prep.join(" "),
                err_set = err_set.join(" "),
            );
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({shim_params}) => {{ {body} }};"
            );
        }
        // A wasm i64 result must be a BigInt in range. `BigInt(..)` is a no-op
        // on a value that already is one and rescues a JS API that hands back a
        // Number, which would otherwise be a TypeError at the boundary;
        // `asIntN` wraps a u64 above 2^63 into the signed representation Rust
        // reinterprets.
        Ret::Value(tag) if tag == "i64" || tag == "u64" => {
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({params}) => BigInt.asIntN(64, BigInt({call}));"
            );
        }
        Ret::Void | Ret::Value(_) => {
            let _ = writeln!(
                js,
                "    imports[{ns}][{import_name}] = ({params}) => {call};"
            );
        }
    }
}

fn next_param(params: &mut Vec<String>) -> String {
    let p = format!("p{}", params.len());
    params.push(p.clone());
    p
}

/// Render a string as a double-quoted JS string literal.
fn js_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\u{2028}' => out.push_str("\\u2028"),
            '\u{2029}' => out.push_str("\\u2029"),
            c if c.is_control() => {
                let _ = write!(out, "\\u{:04x}", u32::from(c));
            }
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    // Only the tests name this type; the emitter infers it from the match.
    use crate::descriptor::SliceElem;

    fn func(ns: &str, import: &str, js: &str, args: Vec<AbiArg>, ret: Ret) -> Descriptor {
        Descriptor {
            kind: Kind::Function,
            namespace: ns.into(),
            import_name: import.into(),
            js_name: js.into(),
            args,
            ret,
            variadic: false,
        }
    }

    #[test]
    fn generates_str_and_numeric_shims() {
        let descriptors = vec![
            func("console", "log", "log", vec![AbiArg::Str], Ret::Void),
            func(
                "performance",
                "now",
                "now",
                vec![],
                Ret::Value("f64".into()),
            ),
        ];
        let js = generate_glue(&descriptors, &[], None);
        assert!(js.contains("imports[\"console\"][\"log\"] = (p0, p1) => globalThis[\"console\"][\"log\"](__wl_str(p0, p1));"));
        assert!(js.contains(
            "imports[\"performance\"][\"now\"] = () => globalThis[\"performance\"][\"now\"]();"
        ));
        assert!(js.contains("export async function instantiate"));
        // The value-table runtime import is always wired.
        assert!(js.contains("imports[\"__wasm_lite\"] = Object.assign(Object.create(null), { __wl_drop: __wl_drop, __wl_spawn: __wl_spawn_unavailable, __wl_schedule: __wl_schedule, __wl_wait_async: __wl_wait_async, __wl_timer_arm: __wl_timer_arm, __wl_timer_cancel: __wl_timer_cancel, __wl_test_pending: __wl_test_pending, __wl_test_pass: __wl_test_pass, __wl_closure_new: __wl_closure_new, __wl_clone: __wl_clone, __wl_num: __wl_num, __wl_bigint: __wl_bigint, __wl_ubigint: __wl_ubigint, __wl_bigint_str: __wl_bigint_str, __wl_str_val: __wl_str_val, __wl_as_f64: __wl_as_f64, __wl_as_bool: __wl_as_bool, __wl_as_str: __wl_as_str, __wl_eq: __wl_eq, __wl_binop: __wl_binop, __wl_unop: __wl_unop, __wl_cmp: __wl_cmp, __wl_is: __wl_is, __wl_checked_div: __wl_checked_div, __wl_num_str: __wl_num_str, __wl_memory_obj: __wl_memory_obj, __wl_module_obj: __wl_module_obj });"));
        assert!(js.contains("const __wl_timers = new Map();"));
    }

    #[test]
    fn u32_args_and_returns_are_reinterpreted_unsigned() {
        // Wasm i32 params/results surface in JS as signed Numbers; u32 values
        // above 2^31 must be normalized with `>>> 0` on their way to JS.
        let descriptors = vec![
            func("ns", "set_id", "set_id", vec![AbiArg::U32], Ret::Void),
            func(
                "ns",
                "pick",
                "pick",
                vec![AbiArg::Opt(Payload::U32)],
                Ret::Void,
            ),
        ];
        let exports = vec![Export {
            name: "next_id".into(),
            args: vec![],
            ret: ExportRet::U32,
        }];
        let js = generate_glue(&descriptors, &exports, None);
        assert!(js.contains(
            "imports[\"ns\"][\"set_id\"] = (p0) => globalThis[\"ns\"][\"set_id\"]((p0 >>> 0));"
        ));
        assert!(js.contains("imports[\"ns\"][\"pick\"] = (p0, p1) => globalThis[\"ns\"][\"pick\"]((p0 ? (p1 >>> 0) : undefined));"));
        assert!(js.contains("function __wl_export_wrapper_0() { __wl_check_live(); const __ret = __wl_instance.exports[\"__wl_export_next_id\"](); return __ret >>> 0; }"));
        assert!(js.contains("export { __wl_export_wrapper_0 as \"next_id\" };"));
    }

    #[test]
    fn overload_keys_slot_on_import_name_but_calls_js_name() {
        let descriptors = vec![func(
            "Math",
            "max2",
            "max",
            vec![AbiArg::Num, AbiArg::Num],
            Ret::Value("f64".into()),
        )];
        let js = generate_glue(&descriptors, &[], None);
        assert!(js.contains(
            "imports[\"Math\"][\"max2\"] = (p0, p1) => globalThis[\"Math\"][\"max\"](p0, p1);"
        ));
    }

    #[test]
    fn long_member_paths_generate_without_quadratic_copying() {
        let js_name = vec!["member"; 50_000].join(".");
        let descriptor = func("ns", "binding", &js_name, vec![], Ret::Void);

        let started = std::time::Instant::now();
        let js = generate_glue(&[descriptor], &[], None);
        let elapsed = started.elapsed();

        assert!(js.ends_with("\n"));
        assert!(
            elapsed < std::time::Duration::from_millis(200),
            "a 50,000-segment descriptor took {elapsed:?}; member-path generation should be linear"
        );
    }

    #[test]
    fn handle_return_is_added_to_the_table() {
        let descriptors = vec![func(
            "JSON",
            "parse",
            "parse",
            vec![AbiArg::Str],
            Ret::Handle,
        )];
        let js = generate_glue(&descriptors, &[], None);
        assert!(js.contains(
            "imports[\"JSON\"][\"parse\"] = (p0, p1) => __wl_add(globalThis[\"JSON\"][\"parse\"](__wl_str(p0, p1)));"
        ));
    }

    #[test]
    fn method_calls_through_the_receiver_handle() {
        let descriptors = vec![Descriptor {
            kind: Kind::Method,
            namespace: "Array".into(),
            import_name: "push".into(),
            js_name: "push".into(),
            args: vec![AbiArg::Handle, AbiArg::Num],
            ret: Ret::Value("f64".into()),
            variadic: false,
        }];
        let js = generate_glue(&descriptors, &[], None);
        assert!(
            js.contains("imports[\"Array\"][\"push\"] = (p0, p1) => __wl_obj(p0)[\"push\"](p1);")
        );
    }

    fn shaped(kind: Kind, js: &str, args: Vec<AbiArg>, ret: Ret) -> Descriptor {
        Descriptor {
            kind,
            namespace: "Element".into(),
            import_name: "b".into(),
            js_name: js.into(),
            args,
            ret,
            variadic: false,
        }
    }

    /// A property read must not be emitted as a call: `el.tagName` and
    /// `el.tagName()` are different programs and only the first one works.
    #[test]
    fn getter_reads_the_property_without_calling_it() {
        let js = generate_glue(
            &[shaped(
                Kind::Getter,
                "tagName",
                vec![AbiArg::Handle],
                Ret::Str,
            )],
            &[],
            None,
        );
        assert!(
            js.contains("const __r = __wl_obj(p0)[\"tagName\"];"),
            "{js}"
        );
        assert!(!js.contains("[\"tagName\"]()"), "{js}");
    }

    #[test]
    fn setter_assigns_the_property() {
        let js = generate_glue(
            &[shaped(
                Kind::Setter,
                "scrollTop",
                vec![AbiArg::Handle, AbiArg::Num],
                Ret::Void,
            )],
            &[],
            None,
        );
        assert!(
            js.contains(
                "imports[\"Element\"][\"b\"] = (p0, p1) => __wl_obj(p0)[\"scrollTop\"] = p1;"
            ),
            "{js}"
        );
    }

    #[test]
    fn constructor_uses_new_on_the_global_class() {
        let js = generate_glue(
            &[shaped(
                Kind::Constructor,
                "URL",
                vec![AbiArg::Str],
                Ret::Handle,
            )],
            &[],
            None,
        );
        assert!(
            js.contains(
                "imports[\"Element\"][\"b\"] = (p0, p1) => __wl_add(new globalThis[\"URL\"](__wl_str(p0, p1)));"
            ),
            "{js}"
        );
    }

    #[test]
    fn indexing_uses_computed_access_on_the_receiver() {
        let get = generate_glue(
            &[shaped(
                Kind::IndexGet,
                "unused",
                vec![AbiArg::Handle, AbiArg::U32],
                Ret::Handle,
            )],
            &[],
            None,
        );
        assert!(
            get.contains(
                "imports[\"Element\"][\"b\"] = (p0, p1) => __wl_add(__wl_obj(p0)[(p1 >>> 0)]);"
            ),
            "{get}"
        );

        let set = generate_glue(
            &[shaped(
                Kind::IndexSet,
                "unused",
                vec![AbiArg::Handle, AbiArg::U32, AbiArg::Handle],
                Ret::Void,
            )],
            &[],
            None,
        );
        assert!(
            set.contains(
                "imports[\"Element\"][\"b\"] = (p0, p1, p2) => __wl_obj(p0)[(p1 >>> 0)] = __wl_obj(p2);"
            ),
            "{set}"
        );
    }

    /// A missing class must answer "not an instance", not throw: bare
    /// `x instanceof undefined` is a TypeError, and a downcast test that kills
    /// the instance is worse than one that returns false.
    #[test]
    fn instanceof_is_guarded_against_a_missing_class() {
        let js = generate_glue(
            &[shaped(
                Kind::InstanceOf,
                "Element",
                vec![AbiArg::Handle],
                Ret::Value("bool".into()),
            )],
            &[],
            None,
        );
        assert!(
            js.contains(
                "typeof globalThis[\"Element\"] === \"function\" && __wl_obj(p0) instanceof globalThis[\"Element\"]"
            ),
            "{js}"
        );
    }

    /// `len` crosses in elements, so the typed array's constructor scales it.
    /// Passing a byte length here would read 4x too far.
    #[test]
    fn numeric_slices_become_typed_array_views() {
        let js = generate_glue(
            &[
                func(
                    "Array",
                    "from_f32",
                    "from",
                    vec![AbiArg::Slice(SliceElem::F32)],
                    Ret::Handle,
                ),
                func(
                    "Array",
                    "from_u32",
                    "from",
                    vec![AbiArg::Slice(SliceElem::U32)],
                    Ret::Handle,
                ),
            ],
            &[],
            None,
        );
        assert!(
            js.contains("new Float32Array(__wl_memory.buffer, p0, p1)"),
            "{js}"
        );
        assert!(
            js.contains("new Uint32Array(__wl_memory.buffer, p0, p1)"),
            "{js}"
        );
    }

    #[test]
    fn generates_export_wrappers() {
        let exports = vec![
            Export {
                name: "add".into(),
                args: vec![ExportArg::Num, ExportArg::Num],
                ret: ExportRet::Value,
            },
            Export {
                name: "is_even".into(),
                args: vec![ExportArg::Num],
                ret: ExportRet::Bool,
            },
            Export {
                name: "tick".into(),
                args: vec![],
                ret: ExportRet::Void,
            },
        ];
        let js = generate_glue(&[], &exports, None);
        assert!(js.contains("function __wl_export_wrapper_0(p0, p1) { __wl_check_live(); const __ret = __wl_instance.exports[\"__wl_export_add\"](p0, p1); return __ret; }"));
        assert!(js.contains("export { __wl_export_wrapper_0 as \"add\" };"));
        assert!(js.contains("function __wl_export_wrapper_1(p0) { __wl_check_live(); const __ret = __wl_instance.exports[\"__wl_export_is_even\"](p0); return Boolean(__ret); }"));
        assert!(
            js.contains("function __wl_export_wrapper_2() { __wl_check_live(); __wl_instance.exports[\"__wl_export_tick\"](); }")
        );
    }

    #[test]
    fn generates_string_export_wrapper() {
        let exports = vec![Export {
            name: "greet".into(),
            args: vec![ExportArg::Str],
            ret: ExportRet::Str,
        }];
        let js = generate_glue(&[], &exports, None);
        assert!(js.contains("const [__a0p, __a0l] = __wl_pass_str(p0);"));
        assert!(js.contains("__wl_instance.exports[\"__wl_export_greet\"](__a0p, __a0l)"));
        assert!(js.contains("__wl_instance.exports.__wl_free(__a0p, __a0l);"));
        assert!(js.contains("const __s = __wl_str(__p, __l);"));
    }

    #[test]
    fn import_keys_cannot_reach_object_prototypes() {
        let descriptor = func("__wasm_lite", "__proto__", "call", vec![], Ret::Void);
        let js = generate_glue(&[descriptor], &[], None);
        assert!(js.contains("const imports = Object.create(null);"));
        assert!(js.contains(
            "imports[\"__wasm_lite\"] = Object.assign(Object.create(null), { __wl_drop:"
        ));
        assert!(js.contains("imports[\"__wasm_lite\"][\"__proto__\"] = () =>"));
    }

    #[test]
    fn export_descriptor_names_are_always_quoted_data() {
        let export = Export {
            name: "x\"); globalThis.pwned = true; //".into(),
            args: vec![],
            ret: ExportRet::Void,
        };
        let js = generate_glue(&[], &[export], None);
        assert!(!js.contains("export function x"));
        assert!(js.contains(
            "__wl_instance.exports[\"__wl_export_x\\\"); globalThis.pwned = true; //\"]()"
        ));
        assert!(js.contains(
            "export { __wl_export_wrapper_0 as \"x\\\"); globalThis.pwned = true; //\" };"
        ));
    }
}
